UPDATE shop_items s
SET price = GREATEST(s.price, m.price),
    alt_source_url = m.alt_url,
    config_options = CASE
      WHEN s.config_options IS NOT NULL AND m.price > s.price
      THEN jsonb_set(s.config_options, '{base_price}', to_jsonb(m.price))
      ELSE s.config_options
    END
FROM m
WHERE s.name = m.prod_name
  AND s.region = m.region
  AND s.reserved_user_id IS NULL
  AND s.active;
